                       LocalDateTime now) {
        jdbc.update("""
                        INSERT INTO package_item
                            (package_id, evidence_key, frozen_seal_version, return_batch_id, returned_at, created_at)
                        VALUES (?, ?, ?, NULL, NULL, ?)
                        """,
                packageId, evidenceKey, frozenSealVersion, now);
    }

    /**
     * 查询组合包全部明细，按证物键稳定排序。
     */
