        assertThat(body.get("batches")).hasSize(1);

        // 已归还证物再次归还：409，整批不落账（evs[1] 仍未归还）
        assertThat(returnBatch("alice", packageKey, "recv-r1", "recv-r2",
                List.of(returnItem(evs.get(0), 1), returnItem(evs.get(1), 1)))
